{"content": "     1|#include "../inc/game_engine.h"
     2|#include <stdlib.h>
     3|
     4|// ==========================================
     5|// 静态全局状态变量（用于本局游戏的计分追踪）
     6|// ==========================================
     7|static uint32_t total_score = 0;
     8|static uint32_t current_combo = 0;
     9|static uint32_t max_combo = 0;
    10|static uint32_t max_possible_score = 0; // 理论最高分，用于计算准确率
    11|static uint32_t total_judged_notes = 0; // 已判定的音符数量
    12|
    13|// 重置计分系统（新局开始时调用）
    14|void ResetScoreSystem(void) {
    15|    total_score = 0;
    16|    current_combo = 0;
    17|    max_combo = 0;
    18|    max_possible_score = 0;
    19|    total_judged_notes = 0;
    20|}
    21|
    22|// ==========================================
    23|// 计分与结算模块
    24|// ==========================================
    25|
    26|// 内部调用：根据判定结果更新分数和连击数[cite: 1]
    27|void UpdateScoreAndCombo(JudgeResult result) {
    28|    uint32_t base_score = 0;
    29|    float multiplier = 1.0f;
    30|
    31|    // 1. 处理基础分与断连逻辑[cite: 1]
    32|    switch (result) {
    33|        case JUDGE_PERFECT:
    34|            base_score = 10;          // Perfect 基础分 10 分[cite: 1]
    35|            current_combo++;
    36|            break;
    37|        case JUDGE_GOOD:
    38|            base_score = 5;           // Good 基础分 5 分[cite: 1]
    39|            current_combo++;
    40|            break;
    41|        case JUDGE_MISS:
    42|            base_score = 0;           // Miss 基础分 0 分[cite: 1]
    43|            current_combo = 0;        // 断连处理[cite: 1]
    44|            break;
    45|        default:
    46|            return;
    47|    }
    48|
    49|    // 2. 更新最大连击数
    50|    if (current_combo > max_combo) {
    51|        max_combo = current_combo;
    52|    }
    53|
    54|    // 3. 计算连击加成：每满10连击，分数倍率增加10%（例如10连击×1.1，20连击×1.2）[cite: 1]
    55|    multiplier = 1.0f + ((current_combo / 10) * 0.1f);
    56|
    57|    // 4. 累加实际得分与理论最高分
    58|    total_score += (uint32_t)(base_score * multiplier);
    59|    
    60|    // 理论最高分：假设该音符打出 Perfect，且按当时的连击数计算倍率
    61|    float max_multiplier = 1.0f + (((max_combo + 1) / 10) * 0.1f);
    62|    max_possible_score += (uint32_t)(10 * max_multiplier); 
    63|    
    64|    total_judged_notes++;
    65|}
    66|
    67|// 获取当前游戏结算数据[cite: 1]
    68|GameResultEvent GenerateGameResult(void) {
    69|    GameResultEvent result;
    70|    result.final_score = total_score;
    71|    result.max_combo = max_combo;
    72|    
    73|    // 计算总准确率
    74|    if (max_possible_score > 0) {
    75|        result.accuracy = (float)total_score / (float)max_possible_score;
    76|    } else {
    77|        result.accuracy = 0.0f;
    78|    }
    79|
    80|    // 基于总准确率划分 S/A/B/C/D 五档评级[cite: 1]
    81|    if (result.accuracy >= 0.95f) {
    82|        result.grade = 'S';
    83|    } else if (result.accuracy >= 0.85f) {
    84|        result.grade = 'A';
    85|    } else if (result.accuracy >= 0.70f) {
    86|        result.grade = 'B';
    87|    } else if (result.accuracy >= 0.60f) {
    88|        result.grade = 'C';
    89|    } else {
    90|        result.grade = 'D';
    91|    }
    92|
    93|    return result;
    94|}
    95|
    96|// ==========================================
    97|// 判定系统模块
    98|// ==========================================
    99|
   100|// 接收底层手势事件并进行时间窗口滑动匹配[cite: 1]
   101|void ProcessGestureEvent(uint32_t gesture_time, NoteType gesture_type, Beatmap* map) {
   102|    if (map == NULL || map->current_index >= map->total_notes) {
   103|        return; // 谱面不存在或已结束
   104|    }
   105|    
   106|    // O(1) 查找当前待判定音符[cite: 1]
   107|    NoteObject* target_note = &map->notes[map->current_index];
   108|    
   109|    if (!target_note->is_active) {
   110|        return; 
   111|    }
   112|
   113|    // 计算手势时间与目标音符时间戳的差值[cite: 1]
   114|    int32_t time_diff = (int32_t)gesture_time - (int32_t)target_note->timestamp_ms;
   115|    uint32_t abs_diff = (uint32_t)abs(time_diff);
   116|
   117|    // 判断是否落在最大的判定窗口（Good 窗口：±500ms）内[cite: 1]
   118|    if (abs_diff <= WINDOW_GOOD) {
   119|        
   120|        // 1. 手势类型不匹配 -> 直接判定 Miss[cite: 1]
   121|        if (gesture_type != target_note->type) {
   122|            target_note->result = JUDGE_MISS;
   123|        } 
   124|        // 2. 时间差绝对值 ≤ Perfect 窗口 (100ms) -> Perfect[cite: 1]
   125|        else if (abs_diff <= WINDOW_PERFECT) {
   126|            target_note->result = JUDGE_PERFECT;
   127|        } 
   128|        // 3. 其他情况落在 Good 窗口内 -> Good[cite: 1]
   129|        else {
   130|            target_note->result = JUDGE_GOOD;
   131|        }
   132|        
   133|        // 标记该音符已处理，索引移动到下一个
   134|        target_note->is_active = false;
   135|        map->current_index++;
   136|        
   137|        // 更新分数
   138|        UpdateScoreAndCombo(target_note->result);
   139|        
   140|        // TODO: 这里可以调用 EventBus 将单次判定结果 (target_note->result) 广播出去
   141|    }
   142|}
   143|
   144|// 处理超时未命中 (需要在系统主循环中高频调用)[cite: 1]
   145|void CheckTimeoutMiss(uint32_t current_sys_time, Beatmap* map) {
   146|    if (map == NULL || map->current_index >= map->total_notes) {
   147|        return;
   148|    }
   149|    
   150|    NoteObject* target_note = &map->notes[map->current_index];
   151|    
   152|    if (!target_note->is_active) {
   153|        return;
   154|    }
   155|    
   156|    // 判定条件：当前系统时间已经超过了该音符的最晚命中时间（触发时间 + Good窗口）[cite: 1]
   157|    if (current_sys_time > (target_note->timestamp_ms + WINDOW_GOOD)) {
   158|        target_note->result = JUDGE_MISS;
   159|        target_note->is_active = false;
   160|        map->current_index++;
   161|        
   162|        UpdateScoreAndCombo(JUDGE_MISS);
   163|        
   164|        // TODO: 调用 EventBus 广播 Miss 事件[cite: 1]
   165|    }
   166|}", "total_lines": 165, "file_size": 5694, "truncated": false, "is_binary": false, "is_image": false}

