    39|}
    40|
    41|function errorTemplate(error) {
    42|  return `<section class="screen-page">
    43|    <div class="screen-heading"><div><span class="eyebrow-light">CONNECTION ERROR</span><h2>暂时无法获取数据</h2></div></div>
    44|    <div class="card" style="padding:18px;line-height:1.7;color:#a8b9b6;font-size:10px">
    45|      <p>${error.message || "接口请求失败"}</p>
    46|      <p>请检查左侧 API 地址，或切回 Mock 数据继续演示。</p>
    47|      <button class="primary-button" id="fallbackMock">切回 Mock 数据</button>
    48|    </div>
    49|  </section>`;
    50|}
    51|
    52|async function ensureDashboard() {
    53|  if (!dashboard) dashboard = await adapter.getDashboard();
    54|  return dashboard;
    55|}
    56|
    57|function setActiveNav(view) {
    58|  document.querySelectorAll(".bottom-nav [data-nav]").forEach((button) => {
    59|    button.classList.toggle("is-active", button.dataset.nav === view);
    60|  });
    61|}
    62|
    63|async function navigate(view) {
    64|  cleanupCurrentView();
    65|  cleanupCurrentView = () => {};
    66|  sampler.recalculate(false);
    67|  setActiveNav(view);
    68|  root.scrollTop = 0;
    69|  root.dataset.view = view;
    70|  try {
    71|    if (view === "home") await renderHome();
    72|    else if (view === "beat") await renderBeat();
    73|    else if (view === "nback") await renderNBack();
    74|    else if (view === "focus") await renderFocus();
    75|    else if (view === "coach") await renderCoach();
    76|  } catch (error) {
    77|    root.innerHTML = errorTemplate(error);
    78|    document.querySelector("#fallbackMock")?.addEventListener("click", () => {
    79|      adapter.configure({ mode: "mock" });
    80|      dashboard = null;
    81|      syncConnectionUi();
    82|      navigate("home");
    83|    });
    84|  }
    85|  root.focus({ preventScroll: true });
