    87|
    88|async function renderHome() {
    89|  setLoading();
    90|  const data = await ensureDashboard();
    91|  const analysis = focusEngine.analyze(data.metrics, data.baseline, data.user.goal);
    92|  const dayLabels = ["一", "二", "三", "四", "五", "六", "日"];
    93|  root.innerHTML = `<section class="screen-page home-page">
    94|    <div class="home-hero">
    95|      <div class="hero-copy">
    96|        <span class="eyebrow-light">DAY ${data.user.streakDays} · EXAM MODE</span>
    97|        <h2>早上好。<br>今天也进入心流。</h2>
    98|        <p>${analysis.suggestion.split("。")[0]}。</p>
    99|      </div>
   100|      <div class="score-ring" style="--score:${analysis.score}"><strong>${analysis.score}</strong><small>FOCUS SCORE</small></div>
   101|    </div>
   102|    <div class="metric-strip">
   103|      <div class="metric card"><span>反应速度</span><strong>${data.metrics.reactionMs}<small> ms</small></strong><small>较基线更快</small></div>
   104|      <div class="metric card"><span>记忆正确</span><strong>${data.metrics.memoryAccuracy}<small>%</small></strong><small>稳定训练中</small></div>
   105|      <div class="metric card"><span>今日专注</span><strong>${data.metrics.focusMinutes}<small> min</small></strong><small>超过基线</small></div>
   106|    </div>
   107|    <div class="section-label"><span>开始训练</span><span>智能难度已开启</span></div>
   108|    <div class="module-grid">
   109|      <button class="module-card" data-open="beat" style="--module-color:var(--gold)"><i>♪</i><strong>BeatFlicks</strong><small>体感节奏 · 3 分钟</small></button>
   110|      <button class="module-card" data-open="nback" style="--module-color:var(--pink)"><i>N</i><strong>Synapse-N</strong><small>工作记忆 · 2-Back</small></button>
   111|      <button class="module-card" data-open="focus" style="--module-color:var(--teal)"><i>◉</i><strong>Aura-Focus</strong><small>呼吸引导 · 4 分钟</small></button>
   112|      <button class="module-card" data-open="coach" style="--module-color:var(--blue)"><i>✦</i><strong>AI 教练</strong><small>五维画像 · 个性建议</small></button>
   113|    </div>
   114|    <div class="section-label"><span>本周专注趋势</span><span>+12% ↑</span></div>
   115|    <div class="trend-card card"><div class="trend-bars">${data.weekly.map((value, index) => `<i class="trend-bar" style="--value:${value}"><span>${dayLabels[index]}</span></i>`).join("")}</div></div>
   116|  </section>`;
   117|  root.querySelectorAll("[data-open]").forEach((button) => button.addEventListener("click", () => navigate(button.dataset.open)));
   118|}
   119|
